      en: ["Glacial ridge", "Geological protected area", "Historical significance", "Height approx. 127 meters"],
      es: ["Cresta glacial", "Área de protección geológica", "Importancia histórica", "Altura aprox. 127 metros"],
      pt: ["Crista glacial", "Área de proteção geológica", "Importância histórica", "Altura aprox. 127 metros"],
